// Üretilen dosya: tool/ozgun/uret.py. Doğa · Doğa gözlemi, mevsimler, iz sürme ve doğada güvenlik (zor).
const ozNature14Zor = <(String, String, List<String>, String)>[
  ('Dünya Ocak başında Güneş\'e en yakın konumundadır, ama Kuzey Yarımküre o sırada kıştır. Bu durum mevsimlerin Güneş\'e olan uzaklıkla açıklanamayacağını en iyi nasıl gösterir?', 'Aynı anda iki yarımkürede zıt mevsimlerin yaşanmasıyla', ['Kış aylarında Güneş\'in gökyüzünde daha büyük görünmesiyle', 'Ekvatorda yıl boyunca sıcaklığın hiç değişmemesiyle', 'Kutuplarda yılda yalnız bir kez gece olmasıyla'], 'Güney Yarımküre\'de Ocak ayı yaz yaşanırken Kuzey\'de kış olur; uzaklık belirleyici olsaydı iki yarımkürede aynı mevsim görülürdü. Asıl neden eksen eğikliğinin ışınların geliş açısını değiştirmesidir.'),
  ('Ekvator çevresindeki yerlerde gündüz süresi yıl boyunca yaklaşık 12 saat civarında kalır. Bunun nedeni nedir?', 'Güneş yolu ufka dik; yay her mevsim yarım daire', ['Ekvatorun Güneş\'e Dünya\'nın başka bir yerinden daha yakın olması ve ışığın hep aynı açıyla gelmesi', 'Atmosferin ekvatorda ışığı yıl boyunca aynı oranda yansıtıp gündüzü sabit tutması', 'Dünya\'nın dönüş hızının ekvatorda en yavaş olması ve günün her mevsim eşit kalması'], 'Ekvatorda Güneş\'in yörüngesi ufku hep yaklaşık yarım yay boyunca kestiğinden gündüz ile gece süresi yıl boyu birbirine çok yakındır.'),
  ('Kuzey Yarımküre\'de en sıcak aylar gündönümünden bir iki ay sonra, Temmuz ve Ağustos\'ta yaşanır. Bu gecikmeyi en iyi hangisi açıklar?', 'Kara ve deniz ısıyı depolar; Güneş enerjisi azalsa da sıcaklık bir süre artmayı sürdürür', ['Dünya Temmuz ayında Güneş\'e en çok yaklaştığı için sıcaklık doruğa Temmuz\'da çıkar, bu bir yörünge etkisidir', 'Haziran\'da ölçülen gün uzunluğunun hesap hatasıyla olduğundan fazla bulunması sonucunda', 'Ağustos ayında Dünya\'nın eksen eğikliğinin artması yüzünden Güneş ışınlarının daha dik gelmesi'], 'Isı girdisi yaz gündönümünde en yüksektir, ama su ve toprağın ısı kapasitesi nedeniyle yüzey ısınmayı sürdürür ve sıcaklık zirvesi gündönümünden sonra görülür.'),
  ('Mart ve Eylül ayları çevresinde günlerin kısalma ya da uzama hızı en fazladır, haziran gündönümü çevresinde ise gün uzunluğu günler boyu neredeyse değişmez. Bu gözlem neyle açıklanır?', 'Gündönümünde Güneş\'in deklinasyonu yavaş değişir, ekinokslarda ise en hızlı değişir', ['Dünya\'nın yörünge hızının gündönümlerinde geçici olarak sıfıra düşmesi ve gün uzunluğunun donması', 'Atmosferin ışığı ekinokslarda daha çok kırması ve gün uzunluğunu hızla değiştirmesi', 'Gün uzunluğunun yalnızca Ay\'ın evrelerine bağlı olup Güneş yüksekliğiyle ilgisinin bulunmaması'], 'Güneş\'in gökteki deklinasyonu sinüs eğrisi gibi değişir; zirve ve diplerde eğim yatay, ekinokslarda en diktir, bu da gün uzunluğundaki değişimin hızını belirler.'),
  ('Ekinoks günü gündüz süresi tam 12 saat değil, birkaç dakika daha uzundur. Bu fark hangi iki etkenden doğar?', 'Atmosferik kırılma ve doğuşun diskin üst kenarına göre sayılması', ['Dünya\'nın günberiye yaklaşması ve Ay\'ın çekimiyle ışığın gündüz tarafına yansıması', 'Eksen eğikliğinin tam 23,5° olmaması ve takvim yılının güneş yılıyla birebir örtüşmemesi', 'Ekvator çevresinin kutup çevresinden uzun olması yüzünden doğuşun gecikmesi'], 'Atmosfer ışığı kırdığı için Güneş ufkun biraz altındayken bile görünür; ayrıca doğuş, diskin üst kenarı belirdiğinde sayılır. Bu yüzden gerçek eşitlik (equilux) ekinokstan birkaç gün önce olur.'),
  ('Kyoto\'da kiraz çiçeklerinin tam açma tarihleri bin yıldan uzun süredir yazılı kayıtlara geçmiştir. Bu kayıtlar bilim insanları için neden değerlidir?', 'İlkbahar sıcaklıklarının uzun dönem değişimini gösteren bir iklim göstergesi sunarlar', ['Ağacın yaşını doğrudan veren, sıcaklıktan bağımsız ve her yıl aynı gün görülen bir veri sunarlar', 'Toprağın tuz oranını uzun yıllar boyunca doğrudan ölçmeye yarayan bir veri kaynağı sunarlar', 'Yağış miktarını termometre gibi doğrudan ve her gün için ayrı ayrı ölçmeye yararlar'], 'Çiçeklenme zamanı ilkbahar sıcaklığına duyarlı olduğundan bu kayıtlar termometreden önceki dönemler için vekil (proxy) iklim verisidir.'),
  ('Badem ağacı Türkiye\'de Şubat ya da Mart başında çiçek açabilir. Bu erken çiçeklenme, geç donlu bir yılda neden büyük risk yaratır?', 'Açmış çiçekler ve genç meyve taslakları donla zarar görür, rekolte düşer', ['Ağacın kökleri donarak ağaç birkaç gün içinde tamamen ölür ve bahçe yeniden dikilmek zorunda kalır', 'Yapraklar sonbaharda olması gerekenden çok erken dökülür ve ağaç kışa hazırlıksız girer', 'Çiçeklerin renk pigmentleri bozulur ve çiçekler böcekler tarafından fark edilmez hâle gelir'], 'Erken çiçeklenme tozlaştırıcı böcekler uyanmadan gerçekleşirse döllenme azalır; üstelik açmış çiçekler eksi derecelerde kolayca zedelenir.'),
  ('Elma ve kiraz gibi ılıman bölge meyve ağaçları, tomurcuklarının kışın dinlenme durumundan çıkabilmesi için belirli bir süre soğuk saat toplamaya gereksinim duyar. Çok ılık geçen bir kışta ne beklenir?', 'Tomurcuk açılması düzensizleşir ve verim düşer', ['Tomurcuklar Ocak\'ta hemen açar ve çok verimli olur', 'Ağaçlar herdem yeşil hâle gelir', 'Meyveler daha iri ve daha tatlı olur'], 'Soğuklama gereksinimi karşılanmazsa tomurcuk dinlenmeden çıkamaz; çiçeklenme geç, düzensiz ve zayıf olur.'),
  ('Güneşli günler ve soğuk ama donsuz geceler olan bir sonbaharda yaprak renklerinin daha canlı kırmızı olması beklenir. Bunun nedeni nedir?', 'Soğuk yüzünden şeker yaprakta birikip antosiyanini artırır', ['Gündüz klorofilin güçlü ışıkla yeniden yapılması, kırmızı rengin gece soğuğuyla birlikte yaprakta kalmasını sağlar', 'Soğuk havanın yapraklardaki kırmızı ışığı daha çok yansıtması ve bu yüzden daha kırmızı görünmesi', 'Soğuk gecelerin yaprak dokularını suya doyurup yaprağın şeffaflaşmasına yol açması'], 'Gece soğuğu şekerlerin yaprakta kalmasına, bu da kırmızı pigment üretiminin artmasına yol açar; kış donu ise yaprakları erken öldürüp rengi bozar.'),
  ('Dendrokronolojide farklı kütüklerin halka desenleri üst üste bindirilerek tarihlenir. Bu "çapraz tarihleme"nin dayandığı düşünce nedir?', 'Ortak iklim etkisiyle halka desenleri birbirine benzer', ['Her ağacın halkaları kendine özgü, bölgedeki başka hiçbir ağaçla eşleşmeyen bir desen oluşturur', 'Halka genişliği yalnızca ağacın cinsine bağlı olup iklimle ya da yıllarla ilgili değildir', 'Halka sayısı her yıl iki katına çıkarak iklim kayıtlarını bozar ve tarihlemeyi olanaksız kılar'], 'İklim değişkenleri aynı bölgede ağaçlara benzer etki ettiğinden halka genişlik dizileri çakıştırılarak eski odun örneklerinin kesin takvim yılı bulunur.'),
  ('Kışın güneşli ve rüzgârsız, açık bir gecede vadi tabanında don olurken yamaçların üst kesimleri daha ılık kalabilir. Bunun nedeni nedir?', 'Soğuk, yoğun hava aşağı akıp vadi tabanında birikir', ['Isınan hafif hava vadiye inip tabanda birikir, yamaçlar ise geceleri Güneş\'e yakın olduğundan ısınır', 'Dağ zirveleri Güneş\'e daha yakın olduğundan gece bile yamaçlar vadi tabanından daha ılık kalır', 'Vadi tabanında geceleri Ay ışığıyla ısınan toprak havayı yamaçlara göre daha çok soğutur'], 'Yerden ısı yayılımıyla soğuyan ağır hava yamaçlardan aşağı süzülür ve vadi tabanında soğuk hava gölü oluşturur; bu yüzden bağ ve bahçelerde don çukurlarda başlar.'),
  ('Kuzey Yarımküre\'de kışın dolunay gökyüzünde yazın dolunaydan daha yüksekte görünür. Bunu en iyi açıklayan nedir?', 'Dolunay Güneş\'in karşısındadır; kışın Güneş alçakta olduğundan dolunay yüksekte seyreder', ['Kışın Ay, Dünya\'ya yazdakinden daha yakın olduğundan gökyüzünde daha yüksek bir yol izler', 'Ay\'ın yörünge düzlemi kışın dikleştiğinden dolunay her zaman başucunda görünür', 'Dünya\'nın dönüşü kışın yavaşladığından dolunay daha yüksek ve daha uzun süre gökte kalır'], 'Dolunay Güneş\'in tersi yönde bulunur; Güneş kışın gökte alçak yol izlediğinden dolunay yüksek bir yol çizer, yazın ise tersi olur.'),
  ('Kuzey Yarımküre\'de Güney Haçı takımyıldızı Türkiye\'nin büyük bölümünden görülemez, ama Avustralya\'dan ya da Güney Afrika\'dan rahatça görülebilir. Bunun nedeni nedir?', 'Güney göksel kutbuna yakın olduğundan, Türkiye\'den görünen göğün altında kalır', ['Güney Haçı yalnız yaz mevsiminde ortaya çıkar, Türkiye\'de ise yaz bulutlu geçer', 'Haçın parlaklığı Avustralya\'da yaklaşık on kat daha yüksektir ve Türkiye\'den seçilemez', 'Türkiye\'nin üzerinde sürekli bulut tabakası bulunduğundan haç takımyıldızı ancak güneyden görülür'], 'Gözlemcinin enlemi hangi gök bölümünü görebileceğini belirler; Güney Haçı güneye çok yakın olduğundan Türkiye\'den ufkun altında kalır.'),
  ('Gece gökyüzünde parıldamayan, sabit ışıkla görünen parlak bir cisim yıldızdan çok gezegen olabilir. Bu fark neye bağlıdır?', 'Disk görünümlü gezegen ışığı daha az titrer', ['Gezegenlerin kendi ışığını yayması, yıldızların ise yalnızca Güneş ışığını yansıtması', 'Gezegenlerin Güneş\'ten daha büyük ve daha parlak olması yüzünden ışığın titrememesi', 'Yıldızların Dünya\'ya gezegenlerden daha yakın olması nedeniyle ışıklarının daha sabit görünmesi'], 'Yıldızlar nokta kaynak gibi göründüğünden atmosfer türbülansı ışığı titretir; gezegenler küçük bir disk gibi görünüp daha durgun parlar.'),
  ('Türkiye\'de güneye bakan bir yamaçta kar kuzeye bakan yamaçtan daha erken erir ve bitki örtüsü daha kurak görünür. Bu farkın nedeni nedir?', 'Güney yamaç Güneş ışınlarını daha dik ve uzun süre alır', ['Güney yamaçlarda rüzgâr hiç esmediği için karlar kendi kendine erir', 'Kuzey yamaç, Güneş\'e güney yamaçtan daha yakın olduğu için karı geç eritir', 'Güney yamaçta toprağın hiç kaya içermemesi ısı kaybını azaltıp karı eritir'], 'Kuzey Yarımküre\'de güneye bakan yamaçlar doğrudan ve daha dik gelen ışınla daha çok ısınır, kar erken erir ve toprak daha çabuk kurur.'),
  ('Büyütmesi yüksek bir dürbünle (örneğin 12x) elde gözlem yaparken kuş görüntüsünün sürekli titremesi sorun olur. Bu durumun nedeni nedir?', 'Büyütme arttıkça elin küçük titremeleri de aynı oranda büyür', ['Büyütme arttıkça objektif ısınır ve görüntü ısıl dalgalanma yüzünden titremeye başlar', 'Yüksek büyütme ışığı polarize ettiğinden görüntü zaman zaman kayar', 'Büyütme arttıkça lensler ağırlaşır ve dürbün elde sallanmaya başlar'], 'Dürbün büyütme oranı kadar küçük hareketleri de büyütür; bu yüzden yüksek büyütmede tripod, destek ya da geniş duruş gerekir.'),
  ('Bir gözlemci saha defterine "Kuş yuvaya yem getirdi" yerine "Kuş acıkmış yavrularına yem getirdi" yazıyor. Bilimsel gözlem açısından bu cümle için en doğru yorum hangisidir?', 'Gözlem ile yorum karışmıştır; yavruların aç olduğu gözlenmemiş, tahmin edilmiştir', ['Cümle tamamen nesneldir; çünkü kuşun yavrularına yem getirmesi bir gözlemdir ve her zaman doğrudur', 'Cümle daha ayrıntılı ve daha anlaşılır olduğu için bilimsel notlarda tercih edilir', 'Cümledeki "yem" sözcüğü yanlış seçilmiştir, "besin" yazılması gerekirdi'], 'İyi saha notlarında görülen olay (gözlem) ile ondan çıkarılan anlam (yorum) ayrı yazılır; "aç olmak" doğrudan görülemeyen bir çıkarımdır.'),
  ('Bir doğa bilimci saha defterini 5 yıl sonra açtığında "Kıyıdaki ağacın dalında bir kuş vardı" notundan bir şey öğrenemiyor. Bu notun ana eksiği nedir?', 'Tür, tarih, yer ve sayı gibi ölçülebilir ve izlenebilir bilgiler yok', ['Notun gereğinden uzun yazılmış olması ve gözlemci duygularını aşırı ayrıntılandırması', 'Notun yanında hiçbir çizim ya da resim bulunmaması, bu yüzden hiç anlaşılmaması', 'Notun el yazısıyla yazılmış olması ve kâğıdın zamanla sararması'], 'Saha notu sonradan başkasının da yararlanabileceği biçimde nesnel, tarihli, konumlu ve niceliksel bilgi içermelidir.'),
  ('Bir öğrenci okulun bahçesinde hem Güneş alan hem gölgede kalan yerde bitki sayısını karşılaştırırken Güneş alan tarafta toprak da farklıdır. Bu sorun ne anlama gelir?', 'Karıştırıcı değişken var; sonuç ışığa mı toprağa mı bağlı belli olmaz', ['Gözlem hatasızdır, çünkü iki alanda da bitki sayısı aynı yöntemle sayılmıştır', 'Örnekleme çok büyüktür ve bu yüzden küçük farklar bile anlamlı sayılmalıdır', 'Veri nesneldir, çünkü ışık dışındaki etkenlerin tümü zaten kontrol altındadır'], 'Işık dışında toprak gibi bir etken de değiştiğinden gözlenen farkın tek nedeni ışık olarak yorumlanamaz.'),
  ('Bir sahil kasabasında dondurma satışları arttıkça boğulma olaylarının da arttığı görülüyor. Bu ilişkiyi en iyi hangisi açıklar?', 'Ortak neden sıcaklıktır; ilişki nedensel değildir', ['Dondurma yemek, vücut ısısını düşürüp kaslarda kramp yaparak boğulma riskini artırır', 'Boğulma olayları arttıkça insanlar daha çok dondurma satın alıp sahilde toplanır', 'Veri yanlış toplanmıştır, çünkü iki olayın zamanla birlikte artması mümkün değildir'], 'Korelasyon nedensellik demek değildir; sıcaklık hem dondurma satışını hem yüzme sayısını (dolayısıyla riski) artıran üçüncü bir etkendir.'),
  ('Bir araştırmacı, bir ormandaki kuş çeşitliliğini incelemek için yalnız orman yolunun kenarında örnek topluyor. Bu yaklaşımın ana sorunu nedir?', 'Örnekleme yanlılığı; örnek ormanı temsil etmez', ['Hiçbir gözlem yapılmamış olması, çünkü yol kenarında kuş bulunamaz', 'Verilerin çok fazla toplanması ve sonuçların karmaşıklaşması', 'Yol kenarında araç gürültüsü nedeniyle kuşların tamamen yok olması'], 'Yol kenarındaki yaşam alanları kenar etkisi nedeniyle iç ormandan farklıdır; seçilen örnekler evreni temsil etmediğinden çıkarım güvenilmez olur.'),
  ('Vatandaş bilimi projelerinde bazı nadir ya da koleksiyonculuk riski taşıyan türlerin kesin konumları neden bulanıklaştırılır?', 'Kaçak toplama ve avcılığın önüne geçmek için', ['Veri boyutunu küçültüp sunucu giderlerini azaltmak için', 'Gözlemcinin kimliğini gizleyip kişisel verilerini korumak için', 'Haritayı daha sade ve estetik göstermek için'], 'Nadir bitki ve hayvanların tam koordinatı yayımlanırsa yasa dışı toplayıcılar türü bulup zarar verebilir; konum, korumayı sağlamak için kasıtlı olarak genelleştirilir.'),
  ('Yakala-işaretle-yeniden yakala yönteminin güvenilir olması için hangi varsayım gerekmez?', 'İşaretli bireylerin zamanla sürekli artması', ['İşaretin hayvana zarar vermemesi', 'İşaretli bireylerin popülasyona rastgele karışması', 'Araştırma süresince popülasyonun kapalı kalması'], 'Yöntem; işaretin zarar vermemesi, iyice karışma ve kapalı popülasyon varsayımına dayanır; işaretli birey sayısının artması ise bir koşul değildir.'),
  ('İki çayır parselinde de 100 bitki sayılmış ve her birinde 4 tür bulunmuştur. A parselinde türlerin her biri 25 bireyle, B parselinde bir tür 97, diğerleri 1\'er bireyle temsil edilmiştir. Hangi çıkarım doğrudur?', 'Zenginlik aynı, ancak A\'nın çeşitliliği yüksektir', ['B parseli daha çeşitlidir, çünkü bir türün çok baskın olması çeşitliliği artırır', 'İki parsel de tür sayısı ve dağılım bakımından tamamen eşit çeşitliliktedir', 'A parselinde tür sayısı daha fazladır, çünkü bireyler daha eşit dağılmıştır'], 'Zenginlik yalnızca tür sayısıdır (iki parselde 4); çeşitlilik ise bireylerin türlere eşit dağılımını da hesaba katar, bu nedenle A parseli daha çeşitlidir.'),
  ('Bir parselde kuadrat sayısı arttıkça bulunan yeni tür sayısındaki artış giderek yavaşlar. Bu durum nasıl yorumlanır?', 'Örnekleme çabası arttıkça bölgedeki türlerin büyük kısmı bulunmuş demektir', ['Yeni tür hiç yoktur ve parselde yaşayan bütün türler ilk kuadratta görülmüştür', 'Gözlemci hata yapmıştır ve sayımın bütünüyle yeniden yapılması gerekir', 'Her kuadrat aynı türleri içerdiğinden örnekleme tekrarlı ve anlamsızdır'], 'Tür birikim eğrisinin yatay hâle gelmesi, yeni örneklerin çok az yeni tür katacağını gösterir; yani tür listesi büyük oranda tamamlanmıştır.'),
  ('Kediler yürürken arka ayaklarını çoğu zaman ön ayakların bıraktığı izin üstüne basar. Bu davranışın izdeki görünümü nasıl olur?', 'Tek sıra, düz çizgi boyunca üst üste binen tek iz görünümü', ['Her adımda dört ayrı pati izinden oluşan, birbirinden uzak aralıklı bir iz grubu görünür', 'Sıralar arasında geniş bir boşluk bırakan, iki paralel çizgi hâlinde bir iz dizisi', 'Yalnız arka ayakların izi seçilir ve ön ayak izleri tamamen silinir'], 'Buna doğrudan kayıt denir; arka ayak ön ayak izine bastığından iz dizisi düzgün ve tek sıra hâlinde görünür, bu tilki ve kedigillerde sık rastlanan bir yürüyüş örüntüsüdür.'),
  ('Kar üzerinde birbirinden uzak iki büyük uzun iz ve önlerinde iki küçük yuvarlak iz grubu gören bir iz sürücü hangi hayvanı düşünmelidir?', 'Tavşan', ['Tilki', 'Yaban domuzu', 'Kurt'], 'Tavşanlar sıçrarken uzun arka ayaklarını ön ayakların önüne indirir; bu yüzden büyük arka ayak izleri öne, küçük ön ayak izleri arkaya düşer.'),
  ('Çiy düşmüş bir sabah patikada iz içinde yaprak parçaları ve kurumuş çamur kırıntıları görülürse izin yaşı hakkında ne söylenir?', 'İz eskidir; sonradan yaprak düşmüş ve kenarları dağılmıştır', ['İz tazedir; hayvan hemen önce geçmiş, yaprak ve çamur kırıntıları sonradan oraya iz bırakılırken düşmüştür', 'İz yaklaşık bir saat önce bırakılmıştır, çünkü kenarlardaki çamur henüz kurumamıştır', 'İzin yaşı bu işaretlerden hiçbir biçimde çıkarılamaz, çünkü her zeminde sonuç aynıdır'], 'Taze izlerin kenarı keskindir ve içi temizdir; üstüne yaprak, toz ya da yağmur damlası düşmüşse iz bunlardan önce oluşmuş, yani daha eskidir.'),
  ('Bir hayvan izinde ön ayakta dört, arka ayakta beş parmak izi görülüyorsa bu iz hangi gruba daha olasıdır?', 'Kemirgenler', ['Köpekgiller', 'Kedigiller', 'Toynaklılar'], 'Sincap ve fare gibi kemirgenlerin ön ayağında dört, arka ayağında beş parmak vardır; köpekgil ve kedigillerde iki ayakta da dört parmak izi görülür.'),
  ('Bir ağaç dalında fidan kabuğu 45° eğik, düzgün bir kesikle koparılmışsa bunu hangi hayvan yapmış olabilir?', 'Tavşan', ['Geyik', 'Yaban domuzu', 'Ayı'], 'Tavşanın üst ve alt kesici dişleri makas gibi temiz ve eğik bir kesik bırakır; geyikgillerin üst ön dişi olmadığı için yırtık ve liflenmiş bir ısırık görülür.'),
  ('Kıyıda görülen bir kuş izinde üç parmak öne, bir parmak arkaya bakıyor. Bu iz hakkında hangi çıkarım doğrudur?', 'Çoğu kuşta görülen tipik bir iz düzenidir', ['Bu iz kesinlikle bir memeli izidir, çünkü kuşlar iz bırakmaz', 'Bu iz yalnızca sürüngenlerde görülür, kuşlarda böyle bir iz oluşmaz', 'Yalnızca baykuş ve papağan gibi kuşlarda görülen nadir bir iz düzenidir'], 'Kuşların çoğu üç parmağı öne, bir parmağı arkaya bakacak biçimde yürür; su kuşlarında parmaklar arasında perde izi de görülebilir.'),
  ('Kuş yavrusunu yuvasında ya da yerde bulan bir yürüyüşçü, "dokunursan anne terk eder" inancını duymuştur. Bu inanç için ne söylenebilir?', 'Kuşların koku duyusu zayıftır; terk kanıtı yoktur', ['Kesinlikle doğrudur; insan kokusu bulaşan yavruyu anne mutlaka terk eder', 'Yalnız ormanlarda yaşayan kuşlar için doğrudur, şehir kuşlarında geçerli değildir', 'Yalnız ilkbaharda doğrudur, çünkü bu dönemde anneler çok hassastır'], 'Kuşlar çoğunlukla koku yerine görme ve işitme ile yön bulur; asıl risk, insan yaklaşınca anne kuşun yavrusunu beslemeyi bırakması ve avcıları çekmesidir.'),
  ('Ormanda tek başına yatan küçük bir ceylan ya da geyik yavrusu bulan kişi ne yapmalıdır?', 'Dokunmadan uzaklaşmalıdır; anne yakında olabilir', ['Yavruyu alıp eve götürmeli ve biberonla beslemelidir', 'Yavruyu en yakın yola taşıyıp orada başkalarının fark etmesini beklemelidir', 'Yavruyu hemen süt ve su vererek beslemeli ve yanından ayrılmamalıdır'], 'Bu yavrular anneyi saklamak için saatlerce tek başına kalır; anne beslenmek için döner. Müdahale yavrunun terk edilmesine ya da avcılara yem olmasına yol açabilir.'),
  ('Gökyüzünde önce ince tüy gibi sirrüs bulutları görülüp ardından bulutların kalınlaşarak alçalması ve güneşin silikleşmesi hangi durumun habercisidir?', 'Yaklaşan sıcak cephe ve uzun süreli yağış', ['Birkaç gün sürecek açık ve durgun hava, çünkü bulutlar yüksekte kalır', 'Ani başlayıp kısa sürecek şiddetli dolu, çünkü bulutlar kalınlaşmıştır', 'Sıcaklığın hızla yükselip havanın kuraklaşması, çünkü Güneş silikleşmiştir'], 'Sirrüs-sirrostratüs-altostratüs-nimbostratüs dizisi sıcak cephenin yaklaşmasına işaret eder ve genellikle uzun süreli yağışla sonuçlanır.'),
  ('Bir kış sabahında rüzgâr güneybatıdan kuzeybatıya dönüyor, sıcaklık birkaç derece düşüyor ve basınç yükselmeye başlıyor. Bu değişim nasıl yorumlanır?', 'Soğuk cephenin geçtiği, havanın soğuyup açıldığı', ['Sıcak cephenin yaklaştığı ve yağışın başlamak üzere olduğu', 'Bir kasırga merkezinin tam üzerinden geçildiği ve rüzgârın yön değiştirdiği', 'Alçak basıncın yaklaştığı ve yağmurun giderek artacağı'], 'Soğuk cephe geçtikten sonra rüzgâr kuzeybatıya döner, soğuk ve kuru hava gelir, basınç yükselir ve bulutlar dağılmaya başlar.'),
  ('Kuzey Yarımküre\'nin orta enlemlerinde "akşam kızıllığı ertesi gün güzel hava getirir" sözü neden zaman zaman doğru çıkar?', 'Batıdan gelen açık ve kuru hava', ['Kırmızı rengin yağmur bulutundan gelmesi ve yağışın hemen ardından başlaması', 'Güneş\'in batarken gökyüzüne ısı yaymasıyla ertesi gün havanın ısınması', 'Kırmızı gökyüzünün her zaman yoğun sis ve bulut anlamına gelmesi'], 'Orta enlemlerde hava sistemleri genellikle batıdan doğuya ilerler; batı ufkunda açık gök, yaklaşan havanın da açık olduğuna işaret eder; yine de kural kesin değildir.'),
  ('Islak ve kuru termometreli bir nem ölçerde (psikrometre) iki termometre arasındaki fark ne kadar büyükse bağıl nem için ne söylenir?', 'Bağıl nem o kadar düşüktür', ['Bağıl nem o kadar yüksektir', 'Bağıl nem değişmez', 'Bağıl nem yüzde yüze yakındır'], 'Islak termometredeki buharlaşma onu soğutur; hava kuruysa buharlaşma hızlı olur ve fark büyür; fark sıfırsa hava neme doymuştur.'),
  ('Aynı gün öğle saatinde yerden 1,5 m ölçülen sıcaklık 30 °C iken asfalt yüzeyinde ölçülen 48 °C\'dir. Bu fark neden önemlidir?', 'Yüzeyde yanık riski var; yürüyüşte yüzey sıcaklığı dikkate alınmalıdır', ['Hava sıcaklığı bu durumda çok önemsizdir, çünkü yüzey sıcaklığı her zaman havayla aynıdır', 'Asfalt soğuk olduğu için ölçüm hatalıdır ve termometre bozulmuş demektir', 'Termometre bozuktur, çünkü asfalt hava sıcaklığından daha soğuk olmak zorundadır'], 'Yüzey sıcaklığı hava sıcaklığından çok yüksek olabilir; hava ölçümü yüzey tehlikesini göstermez, bu yüzden yürüyüş ve hayvan yürüyüşü planlanırken yüzey sıcaklığı da düşünülmelidir.'),
  ('Gece Ay çevresinde geniş, soluk bir halka görülmesinin ardından halk arasında "yağmur gelecek" denmesi ne kadar tutarlıdır?', 'Kısmen tutarlıdır; halka buz bulutlarından olur', ['Tamamen asılsızdır; halenin yağışla hiçbir ilgisi yoktur, tamamen gökyüzü rengi olayıdır', 'Halka yağmur damlalarının bıraktığı iz olup yağmurun çoktan başladığını gösterir', 'Halka yalnız kış mevsiminde görülür, yazın hiç oluşmaz, bu yüzden kural geçersizdir'], 'Ay halesi sirrostratüs buz kristallerinden oluşur; bu bulutlar sık sık ilerleyen bir sıcak cepheden önce gelir, ama her halede yağış çıkmaz.'),
  ('Dağda yağmur altında yürüyen bir kişide dış sıcaklık 5 °C iken şiddetli rüzgâr da vardır. Bu kişide hipotermi riskini en çok ne artırır?', 'Islak giysi ısıyı alır, rüzgâr uzaklaştırır', ['Güneş ışığının gözü yorması ve yürüyüşçünün dikkatini dağıtması', 'Çok miktarda su içmesi ve bunun vücut ısısını düşürmesi', 'Yüksek sesle konuşması ve nefes enerjisini boşa harcaması'], 'Islak giysiler kuru giysilerden çok daha hızlı ısı kaybettirir; rüzgâr yalıtım için gerekli ısınmış hava tabakasını uzaklaştırır. Hipotermi eksi derece olmadan da gelişebilir.'),
  ('Hipotermi geçiren bir kişide titremenin bir süre sonra kesilmesi ve kişinin uykuya dalar gibi olması hakkında hangisi doğrudur?', 'Bu, durumun ağırlaştığını gösterebilir; derhal acil yardım istenmelidir', ['Kişinin iyileştiğini ve artık güvende olduğunu gösterir', 'Kişinin sadece yorgun olduğunu ve uyumasına izin verilmesi gerektiğini gösterir', 'Kişiyi uyutmanın bu aşamada ısıyı korumak için en güvenli yol olduğunu gösterir'], 'Vücut ısı üretme gücünü tükettiğinde titreme durur; bu, orta-ağır hipotermi belirtisidir ve bilinç kaybı ile kalp ritmi sorunları izleyebilir.'),
  ('Hipotermi nedeniyle kişiyi taşırken ya da ısıtırken kol ve bacaklarını kuvvetle ovmaktan kaçınılmasının nedeni nedir?', 'Soğuk kanı çekirdeğe iletip kalp ritmini bozabilir', ['Ovmak kişiyi gereksiz yere yorar ve daha çok üşütür', 'Ovma, deri altındaki yağı eriterek vücut ısısını daha da düşürür', 'Kollar ve bacaklar donmuş olduğundan ovulunca kırılabilir'], 'Ağır hipotermide uç bölgelerdeki soğuk kanın birdenbire merkeze dönmesi çekirdek ısısını daha da düşürebilir; ayrıca soğuktan zedelenmiş dokular hırpalanmamalıdır.'),
  ('Arı sokması sonrası hangi belirtiler anafilaksi (ağır alerji) şüphesi doğurur ve acil müdahale gerektirir?', 'Yüzde ve dilde şişme ile nefes darlığı', ['Yalnızca sokma yerinde hafif kızarıklık', 'Birkaç saat süren hafif kaşıntı', 'Sokma yerinde küçük ele gelir şişlik'], 'Anafilaksi hızlı ilerler; solunum yollarında şişme ve kan basıncında düşme görülebilir. Bu kişi derhal acile ulaştırılmalı, kendi adrenalin kalemi varsa kullanılmalıdır.'),
  ('Doğada tanıyamadığınız bir bitkiyi ya da mantarı yemek konusunda en güvenli kural hangisidir?', 'Kesin olarak tanımıyorsanız hiç yememek', ['Bir parçasını deneyip tepkisini beklemek', 'Hayvanların yediği her bitkiyi yemek', 'Pişirince tümünün güvenli olacağını varsaymak'], 'Birçok zehirli türün yenilebilir türlere benzemesi ve bazı zehirlerin pişmeyle ya da bekleme ile etkisiz hâle gelmemesi nedeniyle tek güvenli kural, emin olmadan yememektir.'),
  ('Akarsu geçerken akıntının yaklaşık dizlere kadar çıktığı ve güçlü olduğu bir yerde ilerlemek neden risklidir?', 'Akıntı 15 cm suda bile düşürebilir', ['Su her zaman çok soğuktur', 'Sığ su olduğu için ayak ıslanır', 'Akıntı yalnızca balıklar için tehlikelidir'], 'Su hızı arttıkça yüke binen kuvvet hızın karesiyle artar; hızlı akan sığ su bile dengeyi bozabilir, dizde ise kuvvet ve kayma riski çok yükselir.'),
  ('Dağda kar üzerinde yürürken ayağın altından alçak bir "woomph" sesiyle kar tabakasının çökmesi ve çevrede çatlaklar oluşması neyi gösterir?', 'Zayıf bir katmanın çöktüğünü ve riskin yüksek olduğunu', ['Karın tamamen sağlam olduğunu', 'Hava sıcaklığının düştüğünü', 'Altta bir mağara olduğunu'], 'Bu ses, altta zayıf bir katmanın çökmesiyle kar levhasının hareketlendiği anlamına gelir ve çığ için güçlü bir uyarıdır.'),
  ('Hızla yükselen sıcaklıkla güneşli bir öğleden sonra kar kütlesi yumuşayınca hangi tür tehlike artar?', 'Islak kar çığı', ['Toz çığı hiç olmaz', 'Kuru kar çığı yalnızca geceleri olur', 'Yıldırım düşmesi azalır'], 'Güneş ısıtması karın bağlarını zayıflatır; su içeren ağır ıslak kar tabakaları yamaçtan kayabilir. Bu yüzden bahar tırmanışlarında sabah erken saat tercih edilir.'),
  ('Ağrı Dağı (5137 m) tırmanışı planlayan bir grup iki günde zirveye çıkmayı düşünüyor. Bu planla ilgili en doğru değerlendirme hangisidir?', 'Çok hızlı; irtifa hastalığı riski yüksek', ['Güvenli bir plan', 'Aklimatizasyon gerekmez', 'Yalnız hava soğuksa risk vardır'], 'Yüksek irtifa hastalığı çıkış hızıyla ilişkilidir; hızlı çıkışta vücut yeterli kırmızı kan hücresi ve solunum uyumu geliştiremez, bu yüzden aklimatizasyon günleri planlanmalıdır.'),
  ('0,2 mikron gözenekli bir sırt çantası su filtresi hangi mikroorganizma grubunu tutamayabilir?', 'Virüsleri', ['Bakterileri', 'Giardia kistlerini', 'Kriptosporidyum kistlerini'], 'Bakteriler ve protozoa kistleri filtrede kalır; virüsler çok daha küçük olduğundan (yaklaşık 0,02–0,3 mikron) çoğu filtre bunları tam tutamaz, kimyasal ya da UV gerekebilir.'),
  ('Türkiye\'de yaz mevsiminde ormanlık alanlarda izin verilen yerler dışında ateş yakılmamasının temel nedeni nedir?', 'Orman yangınının kolay başlaması', ['Ormanda ışık bulunmaması', 'Ateşin hayvanları besleyememesi', 'Odun miktarının çok olması'], 'Kuru ot ve ağaç örtüsü kıvılcımla kısa sürede tutuşabilir; küçük bir kamp ateşi büyük orman yangınına dönüşebileceğinden izinsiz ateş yasaktır.'),
  ('"Vücut ısısının büyük kısmı baştan kaybedilir" sözü için en doğru değerlendirme hangisidir?', 'Abartılmıştır; baş yaklaşık vücut yüzeyi oranında kaybeder', ['Her zaman doğrudur', 'Baş hiç ısı kaybetmez', 'Yalnız yaşlılarda doğrudur'], 'Baş vücut yüzey alanının yaklaşık yüzde yedisi civarındadır; açıkta kalan bir bölge olarak orantılı ısı kaybı yaşar, ancak yaygın söylentideki yüzde 50–80 doğru değildir.'),
  ('Gece gözle güç seçilen soluk bir cisme bakarken bakışı cismin hafifçe yanına kaydırmak neden yardımcı olur?', 'Kenar bölgede çubuk hücreler daha çoktur', ['Cisim kendiliğinden parlar', 'Göz bebeği daha çok küçülür', 'Beyin renkleri daha iyi ayırır'], 'Merkezî çukurda (fovea) çubuk hücre yoktur; kenar görüşü zayıf ışığa daha duyarlıdır, bu yüzden bakışı hafifçe yana kaydırmak (eğik görüş) soluk nesneyi belirginleştirir.'),
  ('Dağ çayırında tek bir kamp yeri ilk haftalardan sonra solmuş çim izi bırakıyor. Bu durum "dayanıklı yüzey" ilkesiyle nasıl yorumlanır?', 'Hassas bitki örtüsü ezilmiş, kayalık zemin tercih edilmeliydi', ['Çim ezilmeyi sever, solma doğal bir süreçtir', 'Dağ çayırı çok dayanıklıdır, sorun yoktur', 'Dayanıklı yüzey ilkesi doğru bir ilke değildir'], 'Kısa süreli basma bile hassas alpin çayırlarda uzun süre iyileşmeyen çıplak alanlar bırakır; kaya, çakıl ya da zaten kullanılmış yer daha az zarar verir.'),
  ('Doğada rastladığınız taş, çiçek ya da eski bir çanak çömlek parçasını hatıra olarak almak neden uygun değildir?', 'Doğal ve kültürel bütünlüğe zarar verir', ['Çanta ağırlığını artırdığı için uygun olmaz', 'Herkes alsın diye bırakılması gerekir', 'Hatıra olan taşlar kirlenir ve değerini kaybeder'], 'Doğal ve tarihî nesneler bulundukları ortamda bilimsel ve ekolojik değer taşır; arkeolojik malzemeyi toplamak ayrıca yasalara aykırı olabilir.'),
  ('Boz ayı savunma amaçlı bir saldırı yaptığında yere yüzüstü yatıp eller boynun arkasında kenetlenmesinin gerekçesi nedir?', 'Ense ve başı korumak, tehdit olmadığını göstermek', ['Ayıyı yormak için kıpırdamadan beklemek', 'Ayıdan büyük görünmek için kolları açmak', 'Ayıyı korkutup kaçırmak için bağırmak'], 'Savunma saldırısında ayı tehdidi ortadan kaldırmak ister; hareketsizlik saldırının kısa sürede bitmesini sağlayabilir ve ense-kafa korunur.'),
  ('Kamp alanında akşam bırakılan yiyecek artıklarının sabah sincap, fare ya da başka hayvanlar tarafından yendiği görülüyor. Bu durumun uzun vadeli sonucu ne olur?', 'Hayvanlar kampa alışıp sorun çıkarır', ['Hayvanlar azalır, doğa kendini temizler', 'Kamp alanı genişler, otlar çoğalır', 'Yemekler daha çabuk bozulur'], 'Besine kolay ulaşan hayvanlar insanı besin kaynağı olarak görür; bu da kampçıların eşyalarına zarar verme ve ısırma riskini artırır.'),
  ('Ormanda hayvan yavrusunu bulan ve ona dokunmayan bir yürüyüşçünün davranışı için ne söylenebilir?', 'Doğru; anne çoğu zaman yakındadır', ['Yanlış, yavruyu götürmeliydi', 'Yanlış, yavruyu beslemeliydi', 'Yanlış, yavruyu taşımalıydı'], 'Yavru hayvanlar tek başına görünse de annelerinin yakınında olması yaygındır; dokunmak ve kokusu bulaştırmak annenin dönmesini zorlaştırabilir.'),
  ('Büyük bir orman yangınından sonraki yağışlı mevsimde sel ve çamur akması riski neden artar?', 'Toprak su emmez, su hızla akar', ['Yağmurlar yangından sonra daha seyrek yağar', 'Küller yağmuru emer, akışı yavaşlatır', 'Yanmış orman, kendi başına sel getirir'], 'Bitki örtüsü ve yaprak tabakası yağmuru tutar; yanınca bunlar kaybolur, bazı yerlerde toprak su itici bir katmana dönüşür ve su hızla yüzeyden akar.'),
  ('Yere gömülü bir kap kullanan çukur tuzak (pitfall) yöntemiyle örnek toplanırken hayvanların zarar görmemesi için hangi önlem gerekir?', 'Tuzağı sık aralıklarla kontrol edip boşaltmak', ['Tuzağı bir hafta açık bırakmak', 'Kabın içine sıcak su doldurmak', 'Kabı güneşe açık tutmak'], 'Uzun süre kalan canlılar susuzluktan, soğuktan ya da avlanmadan ölebilir; yağmur örtüsü koymak ve günde en az bir kez kontrol etmek zarar riskini azaltır.'),
  ('Aynı gün öğle saatinde yerden 2 cm yükseklikteki sıcaklık, yerden 1,5 m yüksekteki hava sıcaklığından çoğu zaman farklı çıkar. Bunun asıl nedeni nedir?', 'Mikro iklim: yüzey ısınır, rüzgâr etkisi azdır', ['Termometre bozulmuştur, ölçüm değerleri güvenilmezdir', 'Yere yakın havada oksijen bulunmadığı için ısı artar', 'Yerçekimi sıcaklığı yüksekliğe göre değiştirir'], 'Zemin yüzeyi ışınımı emip ısınır; yere yakın hava hareketi azdır, bu yüzden ince bir ısınmış katman oluşur ve küçük canlıların mikro iklimi farklıdır.'),
  ('Bir doğa meraklısı çiçek ziyaretçilerini saymak için 1 m² alanda 10\'ar dakikalık gözlemler yapıyor. Bu yöntemin güçlü yanı nedir?', 'Alan ve süre sabittir, gözlemler karşılaştırılabilir', ['Ziyaretçiler gözlemciyi görünce hiç kaçmaz', 'Gözlem süresi çok kısa olduğu için hata olmaz', 'Hayvanlar kendilerini tanıtarak sayıma yardım eder'], 'Standart alan ve süre, farklı gözlemleri aynı ölçekle karşılaştırmayı mümkün kılar; böylece değişim, gerçek farklardan kaynaklanır.'),
  ('Kuş gözlemi sırasında bir yuvaya yaklaşan fotoğrafçının ana kuşun yem getirmeyi kestiğini fark etmesi durumunda en doğru davranış nedir?', 'Hemen uzaklaşıp yuvayı rahatsız etmemek', ['Fotoğraf için biraz daha yakına yaklaşıp yem vermek', 'Yuvaya dokunup yavruların sağlığını kontrol etmek', 'Ana kuş gelene kadar yuvanın önünde sessizce beklemek'], 'Yuvada rahatsızlık, ebeveynin yem getirmesini ve kuluçkayı aksatır; gözlemci geri çekilmeli ve daha uzak bir noktadan gözlem yapmalıdır.'),
  ('Kuş gözlemcileri üreme mevsiminde bir bölgede kuş sesi kaydını tekrar tekrar çalmaktan neden kaçınmalıdır?', 'Alanını savunan kuşu strese sokar', ['Kayıt çok pahalı olduğundan sık çalınmaz', 'Kuşlar ses kaydını sevdiği için yaklaşır, zarar görmez', 'Ses kaydı kısa sürede bozulur ve kullanılmaz hâle gelir'], 'Kayıt sesi, kuşa bir rakibin girdiğini düşündürür; kuş enerji harcayıp yuva ve yavrularından uzaklaşır, bu nedenle üreme döneminde sınırlı kullanılır.'),
  ('Doğa gözlemcisi bir tilkiyi gece fotoğraflamak için ışığı doğrudan gözlerine tutarsa ne olabilir?', 'Kamaşıp kaçar ya da yönünü kaybeder', ['Hayvan gelip yanınıza oturur', 'Hayvan ışığı sever ve rahatlar', 'Hayvan ışıktan etkilenmez'], 'Parlak ışık gece görüşüne uyumlu gözleri kamaştırır, hayvanı korkutup kaçırır ya da ona zarar verebilir; kırmızı ışık ya da kısık ışık tercih edilir.'),
  ('Dolunaylı gecelerde açık alanda bazı küçük kemirgenlerin etkinliğinin azalması neyi gösterir?', 'Avlanma riski arttığından gizlenirler', ['Kemirgenler ay ışığından hoşlanıp dışarı çıkar', 'Kemirgenler dolunayda uykuya dalar', 'Kemirgenler dolunayda göç eder'], 'Ay ışığı yırtıcıların avı görmesini kolaylaştırdığından kemirgenler daha az açıkta dolaşır; bu davranış avlanma riskine verilen bir tepkidir.'),
  ('Haritalarda eş yükselti eğrilerinin birbirini kesmemesinin sebebi nedir?', 'Aynı noktada iki farklı yükselti bulunamaz', ['Çizgiler kâğıtta çakışırsa mürekkep akar', 'Eğrilerin renkleri farklıdır', 'Kesişmek yasak bir harita kuralıdır'], 'Her eğri sabit bir yükseltiyi gösterir; bir noktanın iki ayrı yüksekliği olamayacağı için eğriler kesişmez (yalnız dik uçurum ya da mağara gibi aşırı durumlarda üst üste biner).'),
  ('Kuzey Yarımküre\'de yaz mevsimi kıştan birkaç gün daha uzun sürer. Bunun nedeni nedir?', 'Temmuz\'da Dünya uzaktır, yörüngede yavaşlar', ['Ocak\'ta Dünya uzak olduğundan yörüngede hızlanır', 'Mevsimlerin gün sayıları takvimle eşit paylaşılmıştır', 'Ay\'ın çekimi yaz aylarını uzatır'], 'Kuzey yazı sırasında Dünya Güneş\'ten uzaktadır ve Kepler\'in ikinci yasasına göre yavaş ilerler; Ocak\'ta ise günberide hızlıdır, bu yüzden kış yaklaşık 89, yaz yaklaşık 93 gündür.'),
  ('Kuzey Yarımküre\'de orta enlemlerde en erken gün batımı genellikle kış gündönümünde değil, ondan birkaç hafta önce olur. Bu durum hangi kavramla ilişkilidir?', 'Zaman denklemi: gerçek ve saat öğlesi farkı', ['Ay evrelerinin yıl içindeki değişmesi', 'Kışın atmosfer kırılmasının artması', 'Gündönümü tarihinin her yıl değişmesi'], 'Dünya\'nın eliptik yörüngesi ve eksen eğikliği nedeniyle gerçek öğle ile saat öğlesi arasındaki fark (zaman denklemi) değişir; bu yüzden en erken gün batımı ile en kısa gündüz aynı güne denk gelmez.'),
  ('Termometre +3 °C gösterirken açık, rüzgârsız bir gecede otlar üzerinde kırağı oluşabilir. Bunun nedeni nedir?', 'Çim yüzeyi ışınımla çevre havadan daha çok soğur', ['Termometre mutlaka yanlış ölçüm yapmıştır', 'Kırağı yalnız Ocak ayında oluşabilir', 'Çimen kendi kendine buz üretir'], 'Havayı ölçtüğümüz 1,5 m yükseklikte sıcaklık yüzeyden yüksektir; açık gecede ışınım soğuması yüzeyi donma noktasının altına indirir.'),
  ('Artım burgusuyla ağacın göğüs hizasından alınan örnekte 62 yıllık halka sayıldı. Ağacın gerçek yaşı hakkında hangisi doğrudur?', 'Fazladır; fidan boyu için geçen yıllar eklenir', ['Daha azdır, çünkü iç halkalar silikleşir', 'Tam 62\'dir, çünkü her halka bir yıldır', 'Hiç hesaplanamaz, ağaç kesilmelidir'], 'Gövde dibinin halkaları göğüs hizasının altındadır; ağaç o yüksekliğe ulaşana dek geçen yıllar örnekte yoktur, bu nedenle gerçek yaş genellikle sayıdan fazladır.'),
  ('Avrupa\'daki bazı ağaçlarda 1816 yılına ait halkaların çok dar olması hangi olayla ilişkilendirilir?', 'Tambora patlamasının soğuttuğu "yazsız yıl"la', ['1816\'da yaşanan çok sıcak bir yazla', 'Çok kurak geçen bir kışla', 'Büyük bir orman yangınıyla'], 'Tambora patlaması stratosfere kükürt aerosolleri taşıyarak 1816\'da Kuzey Yarımküre\'de soğuk, yağışlı bir yaz yarattı; ağaçlar o yıl çok az büyüdü.'),
  ('Uzaydan bitki örtüsünün mevsimsel yeşillenmesini izleyen NDVI (bitki indeksi) hangi ışık farkına dayanır?', 'Yakın kızılötesi yansıması ile kırmızı emilimi', ['Yaprakların mavi ışığı yansıtması', 'Yaprakların gece parlaması', 'Yaprakların morötesi yayması'], 'Sağlıklı yaprak yakın kızılötesi ışığı güçlü yansıtır ve klorofil kırmızıyı emer; ikisinin farkı yeşillik yoğunluğunu verir, bahar yapraklanması ve sonbahar sararması izlenir.'),
  ('Bir bölgede ilkbahar sıcaklıkları son 30 yılda yükselmişse fenolojik kayıtlarda ne beklenir?', 'Yaprak açma ve çiçeklenmenin erkene kayması', ['Yaprak açma tarihlerinin çok geç kalması', 'Çiçeklerin hiç açmaması', 'Bütün ağaçların aynı gün yaprak açması'], 'Birçok bitkide ilkbahar sıcaklığı arttıkça tomurcuk patlama ve çiçeklenme günleri erkene kayar; bu kayma iklim değişikliğinin canlı göstergelerindendir.'),
  ('Kış sonunda karların erime hızını aynı yükseltide güney ve kuzey yamaçlarda karşılaştıran bir gözlemci hangi sonucu bekler?', 'Güney yamaçta daha hızlı', ['Kuzey yamaçta daha hızlı', 'Her iki yamaçta aynı', 'Yamaç yönünün etkisi yoktur'], 'Kuzey Yarımküre\'de güney yamaçlar Güneş\'ten daha çok ısı alır, kar daha çabuk erir; kuzey yamaçlarda kar daha uzun süre kalır.'),
  ('Kuzey Yarımküre\'de rüzgâra sırtınızı dönüp durduğunuzda alçak basınç merkezi nerede olur?', 'Sol tarafınızda', ['Sağ tarafınızın hemen yanında', 'Tam önünüzde, rüzgâra karşı', 'Tam arkanızda, rüzgâr yönünde'], 'Buys Ballot yasası: Kuzey Yarımküre\'de rüzgârı sırtınıza alırsanız alçak basınç sol, yüksek basınç sağ tarafınızdadır; bu Coriolis etkisinden kaynaklanır.'),
  ('Kış sabahlarında vadi tabanında yoğun sis ve duman hapsolurken tepelerde hava berrak kalabilir. Bu durumu en iyi hangisi açıklar?', 'Sıcaklık terselmesi: soğuk hava altta kalır', ['Vadi tabanı Güneş\'e tepelerden daha yakındır', 'Tepelerde rüzgâr hiç esmediği için hava berrak kalır', 'Vadi tabanında oksijen yetersizdir ve sis çıkar'], 'Soğuk ve yoğun hava vadi tabanında birikir, üstte daha ılık hava kapak gibi durur; bu terselme dikey karışımı engelleyip sis ve kirleticileri hapseder.'),
  ('Kutup ışığında en sık görülen yeşil rengin kaynağı nedir?', '100–300 km\'de atomik oksijenin uyarılması', ['Atmosferdeki azotun donarak parlaması', 'Karbondioksitin ışık saçması', 'Hidrojenin yanarak ışıma yapması'], 'Güneş rüzgârından gelen parçacıklar üst atmosferdeki oksijen atomlarını uyarır; yeşil ışıma bu geçişten kaynaklanır, kırmızı ise daha yüksek oksijen, mavi-mor azot kaynaklıdır.'),
  ('Hava sıcaklığı 28 °C ve nem yüksek olduğunda "hissedilen sıcaklık"ın daha yüksek çıkmasına yol açan nedir?', 'Nemin terin buharlaşmasını yavaşlatması', ['Rüzgârın nemle birlikte artması', 'Nemin ısıyı soğurup ortadan kaldırması', 'Basıncın düşerek ısıyı artırması'], 'Ter buharlaşarak vücudu soğutur; hava nemliyse buharlaşma yavaşlar ve vücut ısısını atamaz, bu yüzden ısı indeksi gerçek sıcaklıktan yüksektir.'),
  ('Bir yürüyüşçü gün doğumundan sonra yükselen ince sirrüs bulutlarının ardından rüzgârın güneyden esmeye başladığını ve basıncın düştüğünü görüyor. Bu durumda en akılcı plan nedir?', 'Havanın bozulmasına karşı yürüyüşü kısaltmak', ['Zirveye hızla çıkıp havanın düzelmesini beklemek', 'Bütün eşyaları bırakıp gece yürüyüşü yapmak', 'Rüzgâr güneyden eserken yürüyüşü uzatmak'], 'Bulut, rüzgâr ve basınç bir arada hava bozulmasını gösterir; zirveyi erteleme ya da dönüş saatini öne alma riski azaltır.'),
  ('Çamurda birbirini izleyen tek sıralı küçük pati izleri ve her izin içinde arka ayağın ön ayak izine oturduğu görülüyor. İz sahibi hangi grup olabilir?', 'Tilki gibi küçük bir köpekgil', ['Yaban domuzu gibi toynaklı bir hayvan', 'Sincap gibi ağaçta yaşayan bir kemirgen', 'Geyik gibi büyük bir otçul'], 'Tilki yürürken arka ayağını ön ayak izinin üstüne basar ve dar bir çizgi boyunca düz iz bırakır; yaban domuzu ve geyikte çift toynak izi bulunur.'),
  ('Bir bahçede serçe izleri çift çift, yan yana iniyorken bir karganın izleri tek sıra hâlinde görülüyor. Bunun nedeni nedir?', 'Serçe zıplar, karga yürür', ['Serçe uçarak iner, karga zıplayarak ilerler', 'İkisi de aynı biçimde yürür, fark yoktur', 'Karga ayağını sürükler, serçe topuk üstünde yürür'], 'Serçegillerin çoğu iki ayağıyla birlikte zıplar ve çift iz bırakır; karga ise yürürken sağ-sol ayağı sırayla basar ve tek sıra iz oluşturur.'),
  ('Kuru, çatlamış ve açık renkli bir dışkı ile nemli, parlak ve belirgin kokulu bir dışkı karşılaştırıldığında iz sürücü ne çıkarır?', 'İkincisi daha tazedir', ['İkincisi daha eskidir ve solmuştur', 'İkisi tam aynı yaştadır', 'Dışkıdan yaş hiçbir biçimde çıkarılamaz'], 'Dışkı zamanla kurur, rengi solar ve çatlar; nemli, parlak ve kokulu olanlar yeni bırakılmış olma ihtimali taşır.'),
  ('Ormanda birden öten kuşlardan alarm çağrılarının yoğunlaştığı fark edilirse bu neyi gösterebilir?', 'Yakında tehdit olabilir', ['Yağmurun birkaç dakika içinde başlayacağı', 'Çiçeklenme mevsiminin tamamen sona erdiği', 'Ay evresinin yeni aydan dolunaya geçtiği'], 'Kuşların alarm çağrıları yırtıcıların varlığını duyurur; gözlemci bunu yakın çevrede dikkate almalı ve bir yırtıcıyı ya da başka bir hayvanı aramalıdır.'),
  ('Yerde toplu halde yolunmuş bir kuş kalıntısında tüy sapları sağlam ve bütün görülüyorsa bu iz çoğunlukla kime aittir?', 'Yırtıcı bir kuşa', ['Bir tilkiye', 'Bir tavşana', 'Bir kurda'], 'Yırtıcı kuşlar avlarının tüylerini yolar ve saplar genelde bütün kalır; memeliler ise tüyleri keser ya da ısırarak koparır, saplarda diş izi kalır.'),
  ('Gün içinde güneşli bir bölgede karın üzerinde bırakılmış izlerin kenarlarının erimesi ve genişlemesi bir iz sürücü için hangi sonucu doğurur?', 'İz büyür, yaş tahmini güçleşir', ['İz daha net ve keskin görünür', 'İz küçülür ve sertleşir', 'İz kesin olarak taze demektir'], 'Erime iz çevresini genişletir ve ayrıntıları siler; izin boyutu ve yaşı için daha serin saatlerde ya da gölgeli yerlerde incelenmelidir.'),
  ('Aynı hayvanın izleri iki farklı zeminde (çamur ve kuru toprak) bırakılmışsa izlerin birbirinden farklı görünmesinin nedeni nedir?', 'Zeminin sertliği ve nemi iz ayrıntısını değiştirir', ['Hayvanın türü iki zeminde farklı olur', 'Hayvan arada büyüyüp ayağı genişler', 'Hayvanların izi her zeminde tamamen aynıdır'], 'Yumuşak çamur ayrıntıyı iyi saklar, kuru sert toprak ise yalnızca belirsiz bir basınç bırakır; aynı hayvan bu yüzden farklı izler üretebilir.'),
  ('Bir ormanda sayısız kemirilmiş fidan gövdesi ve yerde kesilmiş dal parçalarının bulunması hangi çıkarımı destekler?', 'Otçul ya da kemirgen baskısının yüksek olduğunu', ['Bölgede hiçbir hayvan bulunmadığını', 'Bölgede yağmurun çok yağdığını', 'Bölgenin tamamen kurak olduğunu'], 'Çok sayıda kemirilmiş fidan, otlayıcıların yerel sıklığının fazla olduğunu ve gençleşmenin baskı altında kaldığını düşündürür.'),
  ('Ayakları donmuş, ama kurtarılmak için uzun yol yürümesi gereken kişi için hangi ilke geçerlidir?', 'Çözülüp yeniden donma daha büyük zarar verir', ['Ayakları ateşte hızla çözmek her zaman doğrudur', 'Ayakları karla güçlü şekilde ovup ısıtmak gerekir', 'Donmuş ayakları suya batırıp bekletmek yeterlidir'], 'Donmuş dokunun çözülüp yeniden donması çok daha ağır hasar verir; bu yüzden ısıtma ancak yeniden donma riski ortadan kalktığında yapılır.'),
  ('Bir ormanda ağaç yoğunluğunu belirlemek için 1 m² boyutlu kuadrat kullanmak neden uygun olmaz?', 'Ağaçlar seyrek; daha geniş parsel gerekir', ['Ağaçlar kuadrata sığmayacak kadar uzun olur', 'Ağaçlar hiçbir yöntemle sayılamaz', 'Kuadrat yalnızca çiçekler için tasarlanmıştır'], 'Kuadrat boyutu hedef canlının büyüklüğüne ve yoğunluğuna uyarlanır; seyrek ağaçlar için örneğin 10 × 10 m parseller seçilir, otlar için 1 m² yeterlidir.'),
  ('İşaretlenen bireylerin tuzaklara daha kolay yakalanma eğilimi gösterdiği bir yakala-işaretle çalışmasında popülasyon büyüklüğü nasıl sapar?', 'Gerçek değerin altında kalır', ['Gerçek değerin üstüne çıkar', 'Hiç sapma olmaz', 'Hesaplamak mümkün olmaz'], 'İşaretliler daha sık yakalanırsa ikinci örnekte işaretli oranı gerçek oranın üstüne çıkar; N = M × C / R formülünde R büyür, tahmin düşer.'),
  ('Vatandaş bilimi verisinin en yaygın sınırlılığı aşağıdakilerden hangisidir?', 'Yol yakınında yoğunlaşan coğrafi yanlılık', ['Verinin hiçbir zaman toplanamaması', 'Verinin hiç doğrulanmaması', 'Verinin yalnızca kışın toplanması'], 'Gözlemler genellikle ulaşımı kolay yerlerde birikir; uzak ve ulaşılması güç alanlar eksik kalır. Bu yüzden analizlerde gözlem çabası ve yer yanlılığı hesaba katılır.'),
  ('Aynı bölgede iki farklı gözlemci ekibi, birinin 10 dakika diğerinin 60 dakika süreyle gözlem yaptığı iki alanı karşılaştırıyor. Bu karşılaştırmanın zayıf noktası nedir?', 'Çaba eşit değil; uzun gözlem daha çok tür bulur', ['Gözlemcilerin çok sakin ve sessiz olması', 'Alanların birbirine çok yakın olması', 'Verinin fazla net ve kusursuz olması'], 'Daha uzun gözlem doğal olarak daha çok birey ve tür kaydettirir; karşılaştırma için süre ve alan standartlaştırılmalı ya da çaba hesaba katılmalıdır.'),
  ('Bir ormanda gün ortasında alınan kuş sayımı ile şafakta alınan sayım arasında büyük fark çıkarsa bu fark neye bağlanabilir?', 'Etkinlik ve ötüşün gün içi değişimi', ['Gözlemcinin dürbün markasının farkı', 'Güneşin renginin saate göre değişmesi', 'Kuşların aniden başka kıtaya gitmesi'], 'Kuşlar sabah erken saatte daha etkin ve daha çok ötüşür; gün ortasında etkinlik azaldığından aynı alanda daha az birey kaydedilir.'),
  ('Gökyüzünde sabit hızla ilerleyen, yanıp sönmeyen, çok parlak bir nokta görüldüğünde bu cisim en olası hangisidir?', 'Uluslararası Uzay İstasyonu gibi bir uydu', ['Yanıp sönen ışıklı bir yolcu uçağı', 'Dünya\'ya çok uzak bir kırmızı yıldız', 'Atmosfere giren bir kayan yıldız'], 'Uydular güneş ışığını yansıtır, uzun süre sabit hızla ve yanıp sönmeden gökte ilerler; uçaklar ise renkli, yanıp sönen ışıklar taşır.'),
  ('Orion kışın, Yaz Üçgeni ise yaz akşamları gökyüzünde görülür. Takımyıldızların mevsimden mevsime değişmesinin sebebi nedir?', 'Dünya\'nın yörüngesi baktığımız yönü değiştirir', ['Yıldızlar mevsime göre hareket edip yer değiştirir', 'Takımyıldızlar sürekli yok olup yenilenir', 'Atmosfer yıldızları mevsime göre gizler'], 'Dünya yörüngesi üzerinde ilerledikçe gece tarafı gökyüzünün farklı bir bölümüne bakar; bu yüzden mevsime göre farklı takımyıldızlar görünür.'),
  ('Bir fotoğraf için çiçeği kopartıp başka yere koymak, hayvanın yuvasını düzeltmek ve bitkileri bastırıp ezmek hangi ilkeye aykırıdır?', 'Bulduğunu bırak, yaban hayatına saygı göster', ['Plan yapma ve hazırlanma ilkesine', 'Ateşin etkisini azaltma ilkesine', 'Yürüyüş hızı ve mola ilkesine'], 'Fotoğraf uğruna doğal ortamı değiştirmek habitatı bozar; gözlemci, doğanın yerini ve işleyişini değiştirmeden gözlemelidir.'),
  ('Sabah ince bir sis içinde güneş doğarken yaz mevsiminde hava durumunu tahmin etmek isteyen biri sisin hızla dağılmasını nasıl yorumlar?', 'Isınma başlamış; hava açılabilir', ['Mutlaka yağmur geliyor demektir', 'Kuvvetli bir rüzgâr çıkacak demektir', 'Hava soğuyup bulutlanacak demektir'], 'Yaz sabahı sisi güneş ısıtmasıyla dağılırsa gün genellikle açık geçer; sis dağılmayıp bulutlanıyorsa durum farklı olabilir.'),
  ('Bir yürüyüşçü sabah kırağıyı, öğleye doğru açık gökyüzünü ve akşam sirrüs bulutlarını gözlüyor. Bu üç gözlem birlikte nasıl yorumlanır?', 'Gece soğuk ve açık; cephe yaklaşabilir', ['Yağmur bitti, bir hafta açık geçecek', 'Yarın kesin kar yağacak', 'Hava değişmeyecek, durum sabit'], 'Kırağı açık, durgun gecenin; sirrüs ise yaklaşan sistemin işaretidir. Sistemin ilerlemesi izlenmeli ve plan buna göre esnek tutulmalıdır.'),
  ('Kuzey Kutup Dairesi\'nin biraz kuzeyindeki bir yerde kutup gecesi sırasında gökyüzü gün boyu simsiyah mıdır?', 'Hayır; Güneş ufkun altında ama mavi renkli bir alacakaranlık ışığı birkaç saat sürebilir', ['Evet, hiç ışık yoktur', 'Hayır, gün boyu parlak gündüzdür', 'Evet, ama yıldızlar da görünmez'], 'Güneş ufkun hemen altında kaldığı sürece atmosfer ışığı saçar; bu mavimsi gün ışığı "mavi saat" olarak adlandırılır ve kutup gecesinin başında ve sonunda daha uzundur.'),
  ('Bir kuş yuvası, yumurtalar görünür durumda ve ebeveyn yakında bekliyorken bulunursa nasıl davranılmalıdır?', 'Yuvaya yaklaşmadan uzaktan, kısa süre gözleyip uzaklaşmak', ['Yumurtaları sayıp fotoğrafını çekmek için yaklaşmak', 'Yuvayı başka bir yere taşımak', 'Yuvaya bir şey bırakmak'], 'Yuvanın çevresinde uzun kalmak ebeveynin yuvaya dönmesini engeller, yırtıcıları çeker ve yuvayı terk ettirebilir; uzaktan ve kısa gözlem uygundur.'),
  ('Vatandaş bilimcilerin istilacı bir bitkiyi ilk kez gördükleri yerde bildirmeleri yönetim açısından neden değerlidir?', 'Erken tespit, yayılmayı kontrol altına almayı kolaylaştırır', ['İstilacılar hep zararsızdır', 'Bildirimler bitkileri artırır', 'Haritaları süsler'], 'Yeni gelen bir istilacı türün sınırlı bir alanda bulunması durumunda temizlik kolaydır; yayıldıktan sonra mücadele çok daha pahalı ve zordur.'),
  ('Aynı protokolle (aynı süre ve yöntemle) onlarca yıl boyunca yapılan kuş sayımlarının verileri neyi mümkün kılar?', 'Popülasyonların uzun dönemli artış ya da azalış eğilimini izlemeyi', ['Yalnızca tek bir günün sonucunu', 'Hayvanların rengini', 'Kuşların sesini'], 'Standart protokol, yıllar arası karşılaştırmayı güvenilir kılar; uzun süreli kayıtlar tür eğilimlerini ve iklim ya da habitat değişimlerinin etkisini ortaya çıkarır.'),
  ('Yere yakın hava sıcaklığı yaklaşık kaç derece olduğunda yağışın kar olarak düşmesi daha olasıdır?', 'Yaklaşık 0 ile 2 °C arasında ve altında', ['Yaklaşık 10 °C', 'Yaklaşık 15 °C', 'Yaklaşık 25 °C'], 'Kar yağışı, yağış katmanının ve yere yakın havanın donma noktasına yakın ya da altında olduğu koşullarda görülür; ılık hava katmanı varsa yağmura dönüşür.'),
  ('Gündüz süresi yazın kuzeye gidildikçe uzar. Türkiye\'de Ardahan\'daki bir gözlemci aynı gün İzmir\'dekine göre gün doğumunu hangi yönde fark eder?', 'Daha erken', ['Daha geç', 'Aynı saatte', 'Hiç fark edemez'], 'Doğuya gidildikçe yerel güneş zamanı ilerler; Ardahan İzmir\'in yaklaşık 15° doğusunda olduğundan Güneş orada kabaca bir saat önce doğar.'),
  ('Güneşli bir günde dik bir yamaçta çam ormanı ile hemen yanındaki çıplak kayalık arasında öğle saatlerinde ölçülen sıcaklık farkının nedeni nedir?', 'Kayalık Güneş ısısını emip daha çok ısınır; orman ise gölge ve terleme ile serin kalır', ['Orman daha çok ısı üretir', 'Kayalık daha çok soğutur', 'Fark yoktur'], 'Çıplak kaya yüzeyi koyu ve kuru olduğundan ışığı daha çok emer ve ısınır; ormanda gölge ve yaprakların terlemesi sıcaklığı düşürür.'),
  ('Kamp alanında akşamdan sönmüş görünen odun külünün sabah içinde parlak kor barındırabilmesinin nedeni nedir?', 'Külün iyi yalıtkan olması ısıyı saatlerce hapseder', ['Odunun suya benzemesi', 'Külün ısıyı hızla yok etmesi', 'Rüzgârın korları yakması'], 'Kül, hava ve ısı akışını azaltan hafif bir örtüdür; altında kalan odun parçaları uzun süre ısınır ve rüzgârla yeniden alevlenebilir.'),
  ('Yüksük otu (Digitalis) bitkisinden elde edilen etken maddelerin zehirli olmasının nedeni nedir?', 'Kalp ritmini bozan glikozitler', ['Sinir uçlarını felç eden mantar zehri', 'Karaciğeri eriten kuvvetli bir asit', 'Akciğeri donduran zehirli bir gaz'], 'Yüksük otu digitoksin gibi kalp glikozitleri taşır; küçük miktarlar ilaç olabilir, ancak yabani bitkiyle çay yapmak ölümcül ritim bozukluğuna yol açabilir.'),
  ('Bir ağacın bir büyüme mevsiminde iki halka oluşturmuş gibi görünmesine (yanlış halka) en olası neden nedir?', 'Kuraklık duraklaması sonrası yağışla yeniden büyüme', ['Ağacın aynı yıl içinde iki kez doğması', 'Ağaca aynı yıl yıldırım çarpması', 'Yaşlılıktan hücre bölünmesinin durması'], 'Büyüme mevsimi içinde kuraklık duraklaması ve sonraki yağış, çift halka izlenimi verebilir; bu nedenle halka sayımı çapraz tarihleme ile doğrulanır.'),
  ('Kuzey Kutup Dairesi\'nin içinde, yaz gündönümü yakınında gece yarısı Güneş\'e bakarsanız Güneş hangi yönde görünür?', 'Kuzey yönünde, ufka yakın', ['Güney yönünde, yüksekte', 'Doğu yönünde, başucuna yakın', 'Batı yönünde, yüksekte'], 'Kuzey Yarımküre\'de yaz gündönümünde gece yarısı Güneş en alçak noktasındadır; bu nokta kuzey yönüne denk gelir, öğle vakti ise güneyde en yüksektir.'),
];
